DECLARE
  d jsonb := $rt$[{"name":"قالب منخفض السعرات","notes":"أقل سعرات ممكنة من وصفات الكتيب. مكوّن من وصفات كتيب الوصفات: فطور، غداء، عشاء، سناك. الأرقام كما في الكتيب. المجموع تقريباً 1194 سعرة (بروتين 123غ، كارب 108غ، دهون 30غ).","meals":[{"kind":"breakfast","title":"زبادي يوناني مع مكسرات وفواكه","method":"المكونات:\n• 200غ زبادي يوناني خالي الدسم\n• 15غ مكسرات (لوز أو جوز)\n• 1 ملعقة صغيرة عسل\n• 50غ توت مشكّل\n\nالطريقة:\n1. نحط الزبادي بوعاء.\n2. نضيف المكسرات المفرومة والتوت.\n3. نزيّنه بالعسل ونقدّمه بارد.","items":[{"food":"زبادي يوناني مع مكسرات وفواكه","portion":"وجبة كاملة","protein":25,"carbs":25,"fat":8}]},{"kind":"lunch","title":"روبيان مشوي مع الكينوا والخضار","method":"المكونات:\n• 150غ روبيان (جمبري) مشوي\n• 150غ كينوا مطبوخة\n• نص كوب فلفل رومي مشوي\n• 1 ملعقة صغيرة زيت زيتون\n• نص ملعقة صغيرة عصير ليمون\n\nالطريقة:\n1. نغسل الروبيان وننشّفه زين، ونتبّله بملح وفلفل أسود وعصير ليمون وفص ثوم مهروس ورشة بابريكا أو كمون (اختياري)، ونتركه 10–15 دقيقة.\n2. الكينوا نطبخها بماء مملّح خفيف (جزء كينوا وجزئين ماء) لين تشرب الماء وتلين، ونتركها تبرد شوي.\n3. نشوي الروبيان بمقلاة شواء أو غير لاصقة مع ملعقة صغيرة زيت زيتون على نار متوسطة عالية، 2–3 دقايق لكل جهة لين يصير زهري ومتماسك.\n4. نشوي الفلفل الرومي بنفس المقلاة أو بالفرن لين ياخذ لون خفيف، ونقطّعه ونخلطه مع الكينوا.\n5. نتبّل الكينوا والفلفل بملح خفيف وفلفل أسود وعصير ليمون زيادة ورشة زيت زيتون إذا احتاج، ونقدّم الروبيان فوقها.","items":[{"food":"روبيان مشوي مع الكينوا والخضار","portion":"وجبة كاملة","protein":38,"carbs":43,"fat":10}]},{"kind":"dinner","title":"معكرونة الدجاج بالكريمة","method":"المكونات:\n• 150غ صدر دجاج مشوي ومقطّع\n• 80غ معكرونة قمح كامل مطبوخة\n• نص كوب حليب قليل الدسم\n• 1 ملعقة صغيرة زيت زيتون\n• 1 ملعقة صغيرة دقيق قمح كامل\n• نص ملعقة صغيرة ثوم بودرة وملح وفلفل\n\nالطريقة:\n1. نسلق المعكرونة بماء مملّح خفيف ونصفّيها، ونحتفظ بشوية من ماء السلق نستخدمها إذا الصوص احتاج تخفيف.\n2. بمقلاة نسخّن ملعقة زيت زيتون على نار متوسطة، ونضيف الدقيق ونحرّكه لين ياخذ لون ذهبي خفيف وريحة محمّصة.\n3. نضيف الحليب بالتدريج مع التحريك المستمر لين يتكاثف ويصير مثل صوص كريمي خفيف، وبعدها نضيف الثوم البودرة والملح والفلفل. وممكن رشة جوزة الطيب أو أوريجانو لطعم ألذ.\n4. نضيف الدجاج والمعكرونة للصوص ونحرّك على نار هادية دقيقتين لين يتغلّفون زين. وإذا صار القوام سميك نضيف شوي من ماء سلق المعكرونة.\n5. نقدّمها سخنة، وممكن نزيّنها ببقدونس مفروم أو فلفل أسود طازج.","items":[{"food":"معكرونة الدجاج بالكريمة","portion":"وجبة كاملة","protein":53,"carbs":33,"fat":10}]},{"kind":"snack","title":"براونيز البروتين بالشوكولاتة","method":"المكونات:\n• 1 سكوب واي بروتين نكهة شوكولاتة\n• 2 ملعقة كبيرة كاكاو بودرة غير محلّى\n• نص كوب زبادي يوناني قليل الدسم\n• ربع كوب حليب لوز غير محلّى\n• 2 ملعقة كبيرة عسل أو ستيفيا\n• بيضة\n• نص ملعقة صغيرة بيكنج باودر\n• نص ملعقة صغيرة فانيلا\n• ربع كوب رقائق شوكولاتة داكنة (اختياري)\n\nالطريقة:\n1. نسخّن الفرن على 180°م ونبطّن صينية صغيرة بورق زبدة.\n2. بوعاء نخفق البيضة، وبعدها نضيف العسل والزبادي والحليب والفانيلا.\n3. نضيف بروتين الشوكولاتة والكاكاو والبيكنج باودر ونخلط زين لين يصير الخليط ناعم.\n4. إذا تحبين طعم أغنى أضيفي رقائق الشوكولاتة الداكنة (بتزيد السعرات).\n5. نسكب الخليط بالصينية ونخبزه 15–18 دقيقة لين تتماسك الحواف ويبقى الوسط شوي رطب.\n6. نتركها تبرد وبعدها نقطّعها 6 مربعات.\n\nملاحظة: القيم لقطعة وحدة، بدون رقائق الشوكولاتة. للصينية كاملة (بدون الرقائق): 417 سعرة، بروتين 42.6غ، كارب 45غ، دهون 10غ.","items":[{"food":"براونيز البروتين بالشوكولاتة","portion":"قطعة (1/6 من الصينية)","protein":7,"carbs":7,"fat":2}]}]},{"name":"قالب عالي السعرات","notes":"أعلى سعرات ممكنة من وصفات الكتيب. مكوّن من وصفات كتيب الوصفات: فطور، غداء، عشاء، سناك. الأرقام كما في الكتيب. المجموع تقريباً 2077 سعرة (بروتين 160غ، كارب 174غ، دهون 83غ).","meals":[{"kind":"breakfast","title":"ساندوتش جبن حلوم مشوي","method":"المكونات:\n• 100غ جبن حلوم المراعي قليل الدسم\n• ساندوتش لوزين 50غ\n• جرجير\n\nالطريقة:\n1. نقطّع الحلوم شرائح.\n2. نسخّن المقلاة بقطرة زيت زيتون، ونحط الحلوم على نار هادية حوالي 3 دقايق لكل جهة، ونقلّبه لين يصير ذهبي.\n3. نضيف الجرجير، وبعدها نشيل الحلوم.\n4. نحمّص الساندوتش بنفس المقلاة شوي لين يصير ذهبي ومقرمش.\n5. نحشي الساندوتش بالحلوم والجرجير، وبالعافية.","items":[{"food":"ساندوتش جبن حلوم مشوي","portion":"وجبة كاملة","protein":32,"carbs":27,"fat":20}]},{"kind":"lunch","title":"أرز بالكاري مع الدجاج والخضار","method":"المكونات:\n• 200غ صدور دجاج\n• 75غ جزر\n• 75غ فلفل رومي\n• 50غ بازيلاء\n• 1 بصلة متوسطة\n• 2 فص ثوم\n• بهارات (كاري، كركم، كمون وغيرها)\n• 1 ملعقة كبيرة زيت\n• 3/4 كوب أرز مطبوخ\n\nالطريقة:\n1. قطّع صدور الدجاج مكعبات. (اختياري: انقعها بالزبادي مع الملح والفلفل 30 دقيقة).\n2. سخّن الزيت والزبدة بقدر عميق على نار عالية.\n3. أضف الدجاج وقلّبه 8–10 دقايق لين يتحمّر من كل الجهات.\n4. أضف البصل والثوم والزنجبيل وقلّب دقيقة.\n5. أضف البهارات (كاري، كركم، بابريكا، كمون، ملح، فلفل أسود) وقلّب زين.\n6. أضف الخضار (جزر، فلفل رومي، بازيلاء) وقلّب الخليط.\n7. أضف معجون الطماطم ومرق الدجاج. تقدر تضيف حليب جوز الهند للصوص الكريمي.\n8. خفّف النار وغطّ القدر واتركه يطبخ بهدوء 15–20 دقيقة لين تنضج الخضار والدجاج.\n9. عدّل الملح والفلفل، وأضف فلفل حار إذا تبي.\n10. قدّمه سخن مع الأرز، ومزيّن بكزبرة طازجة أو نعناع.","items":[{"food":"أرز بالكاري مع الدجاج والخضار","portion":"وجبة كاملة","protein":67,"carbs":51,"fat":25}]},{"kind":"dinner","title":"ستيك اللحم مع البطاطا والخضار","method":"المكونات:\n• 150غ ستيك لحم بقري قليل الدهن\n• 150غ بطاطا مشوية أو مسلوقة\n• كوب خضار سوتيه (فلفل، كوسا، بروكلي)\n• 1 ملعقة صغيرة زيت زيتون\n• ملح، فلفل، أعشاب مجففة\n\nالطريقة:\n1. نتبّل الستيك بالملح والفلفل ونشويه على نار متوسطة لين ينضج على ذوقك.\n2. نطبخ الخضار بمقلاة مع زيت الزيتون لين تصير طرية.\n3. نقدّم الستيك مع البطاطا والخضار.","items":[{"food":"ستيك اللحم مع البطاطا والخضار","portion":"وجبة كاملة","protein":44,"carbs":32,"fat":20}]},{"kind":"snack","title":"بودنق التشوكلت","method":"المكونات:\n• بسكويت Galleta Zero (حوالي 158 كالوري)\n• 2 حبة أوريو (86 كالوري تقريباً)\n• 2غ بودرة كاكاو خام (حوالي 5 كالوري)\n• 25غ بياض بيض (13 كالوري تقريباً)\n• 18غ صفار بيض (58 كالوري تقريباً)\n• 40غ شوفان فوري (حوالي 154 كالوري)\n\nالطريقة:\n1. نطحن البسكويت مع حبتين الأوريو لين يصير فتات ناعم بوعاء يصلح للمايكرويف.\n2. نضيف الشوفان الفوري وبودرة الكاكاو للفتات ونخلطها زين لين تتوزع المكونات الجافة.\n3. نضيف بياض وصفار البيض ونخلط زين لين يصير الخليط متجانس. وممكن نضيف ملعقة أو ملعقتين ماء أو حليب قليل الدسم إذا صار سميك زيادة.\n4. نسكب الخليط بكوب أو طبق صغير يصلح للمايكرويف، ونترك فراغ بسيط لأن الخليط ينتفخ وقت التسوية.\n5. نطبخه بالمايكرويف 60–90 ثانية لين يتماسك السطح ويبقى الوسط طري شوي. الوقت يعتمد على قوة جهازك، ابدأ بـ 60 ثانية وزيّد تدريجياً إذا احتاج.\n\nملاحظة: القيم تقريبية: البروتين 16–17غ (اعتمدنا 16.5) والدهون 17–18غ (اعتمدنا 17.5).","items":[{"food":"بودنق التشوكلت","portion":"صحن","protein":16.5,"carbs":64,"fat":17.5}]}]},{"name":"قالب عالي البروتين","notes":"أعلى بروتين ممكن من وصفات الكتيب. مكوّن من وصفات كتيب الوصفات: فطور، غداء، عشاء، سناك. الأرقام كما في الكتيب. المجموع تقريباً 1848 سعرة (بروتين 209غ، كارب 107غ، دهون 65غ).","meals":[{"kind":"breakfast","title":"بيض مخفوق مع الجبن والديك الرومي","method":"المكونات:\n• 2 بيضة كاملة\n• 3 بياض بيض\n• 100غ شرايح ديك رومي مدخّن قليل الدهون\n• 30غ جبن قريش أو جبن قليل الدسم\n• 1 ملعقة صغيرة زيت زيتون\n• رشة ملح وفلفل أسود\n\nالطريقة:\n1. نسخّن زيت الزيتون بالمقلاة.\n2. نخفق البيض ونضيفه للمقلاة مع شرايح الديك الرومي.\n3. نضيف الجبن بالآخر ونتركه يذوب شوي، ونقدّمه سخن.","items":[{"food":"بيض مخفوق مع الجبن والديك الرومي","portion":"وجبة كاملة","protein":45,"carbs":5,"fat":22}]},{"kind":"lunch","title":"أرز بالكاري مع الدجاج والخضار","method":"المكونات:\n• 200غ صدور دجاج\n• 75غ جزر\n• 75غ فلفل رومي\n• 50غ بازيلاء\n• 1 بصلة متوسطة\n• 2 فص ثوم\n• بهارات (كاري، كركم، كمون وغيرها)\n• 1 ملعقة كبيرة زيت\n• 3/4 كوب أرز مطبوخ\n\nالطريقة:\n1. قطّع صدور الدجاج مكعبات. (اختياري: انقعها بالزبادي مع الملح والفلفل 30 دقيقة).\n2. سخّن الزيت والزبدة بقدر عميق على نار عالية.\n3. أضف الدجاج وقلّبه 8–10 دقايق لين يتحمّر من كل الجهات.\n4. أضف البصل والثوم والزنجبيل وقلّب دقيقة.\n5. أضف البهارات (كاري، كركم، بابريكا، كمون، ملح، فلفل أسود) وقلّب زين.\n6. أضف الخضار (جزر، فلفل رومي، بازيلاء) وقلّب الخليط.\n7. أضف معجون الطماطم ومرق الدجاج. تقدر تضيف حليب جوز الهند للصوص الكريمي.\n8. خفّف النار وغطّ القدر واتركه يطبخ بهدوء 15–20 دقيقة لين تنضج الخضار والدجاج.\n9. عدّل الملح والفلفل، وأضف فلفل حار إذا تبي.\n10. قدّمه سخن مع الأرز، ومزيّن بكزبرة طازجة أو نعناع.","items":[{"food":"أرز بالكاري مع الدجاج والخضار","portion":"وجبة كاملة","protein":67,"carbs":51,"fat":25}]},{"kind":"dinner","title":"ستيك لحم بالفطر مع رز","method":"المكونات:\n• 200غ ستيك برازيلي\n• 100غ رز أبيض مطبوخ\n• فطر بني\n• 1 ملعقة صغيرة زيت زيتون\n• رشة ملح وفلفل أسود وبودرة ثوم\n\nالطريقة:\n1. نسخّن المقلاة على حرارة عالية، ونحط الستيك من جهة الدهن أول دقيقة لين يتحمّر.\n2. بعدها نحطه كامل على المقلاة على نار متوسطة، 3 دقايق لكل جهة إذا نبيه Medium Well.\n3. نضيف الفطر ونقلّبه لين ينضج اللحم.\n4. نقدّمه مع الرز.","items":[{"food":"ستيك لحم بالفطر مع رز","portion":"وجبة كاملة","protein":54,"carbs":27,"fat":14}]},{"kind":"snack","title":"وافل البروتين بالفانيلا","method":"المكونات:\n• 1 سكوب واي بروتين نكهة فانيلا\n• 130غ بياض بيض\n• 60مل حليب لوز غير محلّى\n• 30غ دقيق شوفان\n• نص ملعقة صغيرة بيكنج باودر\n• نص ملعقة صغيرة فانيلا\n• نص ملعقة صغيرة قرفة\n\nالطريقة:\n1. نسخّن آلة الوافل وندهنها بقليل زيت.\n2. نخلط كل المكونات بوعاء لين نحصل خليط سلس.\n3. نسكب الخليط بآلة الوافل ونطبخه لين يصير ذهبي ومقرمش.\n4. نقدّمه مع شوية زبدة لوز أو توت طازج.","items":[{"food":"وافل البروتين بالفانيلا","portion":"قطعة","protein":42.8,"carbs":24,"fat":4}]}]},{"name":"قالب عالي الكارب","notes":"أعلى كارب ممكن من وصفات الكتيب. مكوّن من وصفات كتيب الوصفات: فطور، غداء، عشاء، سناك. الأرقام كما في الكتيب. المجموع تقريباً 2004 سعرة (بروتين 160غ، كارب 203غ، دهون 62غ).","meals":[{"kind":"breakfast","title":"بان كيك البروتين بالشوفان","method":"المكونات:\n• 50غ شوفان مطحون\n• 1 سكوب واي بروتين (Whey)\n• 4 بياض بيض\n• نص ملعقة صغيرة قرفة\n• 120مل حليب لوز غير محلّى\n• نص ملعقة صغيرة زبدة فول سوداني (للتزيين)\n\nالطريقة:\n1. نخلط كل المكونات بوعاء لين يصير الخليط متجانس.\n2. نسخّن مقلاة غير لاصقة ونمسحها بقليل زيت.\n3. نسكب الخليط دوائر صغيرة ونتركها لين تطلع الفقاقيع، وبعدها نقلبها.\n4. نقدّمها مع زبدة الفول السوداني أو شوية عسل.","items":[{"food":"بان كيك البروتين بالشوفان","portion":"وجبة كاملة","protein":38,"carbs":45,"fat":9}]},{"kind":"lunch","title":"أرز بالكاري مع الدجاج والخضار","method":"المكونات:\n• 200غ صدور دجاج\n• 75غ جزر\n• 75غ فلفل رومي\n• 50غ بازيلاء\n• 1 بصلة متوسطة\n• 2 فص ثوم\n• بهارات (كاري، كركم، كمون وغيرها)\n• 1 ملعقة كبيرة زيت\n• 3/4 كوب أرز مطبوخ\n\nالطريقة:\n1. قطّع صدور الدجاج مكعبات. (اختياري: انقعها بالزبادي مع الملح والفلفل 30 دقيقة).\n2. سخّن الزيت والزبدة بقدر عميق على نار عالية.\n3. أضف الدجاج وقلّبه 8–10 دقايق لين يتحمّر من كل الجهات.\n4. أضف البصل والثوم والزنجبيل وقلّب دقيقة.\n5. أضف البهارات (كاري، كركم، بابريكا، كمون، ملح، فلفل أسود) وقلّب زين.\n6. أضف الخضار (جزر، فلفل رومي، بازيلاء) وقلّب الخليط.\n7. أضف معجون الطماطم ومرق الدجاج. تقدر تضيف حليب جوز الهند للصوص الكريمي.\n8. خفّف النار وغطّ القدر واتركه يطبخ بهدوء 15–20 دقيقة لين تنضج الخضار والدجاج.\n9. عدّل الملح والفلفل، وأضف فلفل حار إذا تبي.\n10. قدّمه سخن مع الأرز، ومزيّن بكزبرة طازجة أو نعناع.","items":[{"food":"أرز بالكاري مع الدجاج والخضار","portion":"وجبة كاملة","protein":67,"carbs":51,"fat":25}]},{"kind":"dinner","title":"روبيان مشوي مع الكينوا والخضار","method":"المكونات:\n• 150غ روبيان (جمبري) مشوي\n• 150غ كينوا مطبوخة\n• نص كوب فلفل رومي مشوي\n• 1 ملعقة صغيرة زيت زيتون\n• نص ملعقة صغيرة عصير ليمون\n\nالطريقة:\n1. نغسل الروبيان وننشّفه زين، ونتبّله بملح وفلفل أسود وعصير ليمون وفص ثوم مهروس ورشة بابريكا أو كمون (اختياري)، ونتركه 10–15 دقيقة.\n2. الكينوا نطبخها بماء مملّح خفيف (جزء كينوا وجزئين ماء) لين تشرب الماء وتلين، ونتركها تبرد شوي.\n3. نشوي الروبيان بمقلاة شواء أو غير لاصقة مع ملعقة صغيرة زيت زيتون على نار متوسطة عالية، 2–3 دقايق لكل جهة لين يصير زهري ومتماسك.\n4. نشوي الفلفل الرومي بنفس المقلاة أو بالفرن لين ياخذ لون خفيف، ونقطّعه ونخلطه مع الكينوا.\n5. نتبّل الكينوا والفلفل بملح خفيف وفلفل أسود وعصير ليمون زيادة ورشة زيت زيتون إذا احتاج، ونقدّم الروبيان فوقها.","items":[{"food":"روبيان مشوي مع الكينوا والخضار","portion":"وجبة كاملة","protein":38,"carbs":43,"fat":10}]},{"kind":"snack","title":"بودنق التشوكلت","method":"المكونات:\n• بسكويت Galleta Zero (حوالي 158 كالوري)\n• 2 حبة أوريو (86 كالوري تقريباً)\n• 2غ بودرة كاكاو خام (حوالي 5 كالوري)\n• 25غ بياض بيض (13 كالوري تقريباً)\n• 18غ صفار بيض (58 كالوري تقريباً)\n• 40غ شوفان فوري (حوالي 154 كالوري)\n\nالطريقة:\n1. نطحن البسكويت مع حبتين الأوريو لين يصير فتات ناعم بوعاء يصلح للمايكرويف.\n2. نضيف الشوفان الفوري وبودرة الكاكاو للفتات ونخلطها زين لين تتوزع المكونات الجافة.\n3. نضيف بياض وصفار البيض ونخلط زين لين يصير الخليط متجانس. وممكن نضيف ملعقة أو ملعقتين ماء أو حليب قليل الدسم إذا صار سميك زيادة.\n4. نسكب الخليط بكوب أو طبق صغير يصلح للمايكرويف، ونترك فراغ بسيط لأن الخليط ينتفخ وقت التسوية.\n5. نطبخه بالمايكرويف 60–90 ثانية لين يتماسك السطح ويبقى الوسط طري شوي. الوقت يعتمد على قوة جهازك، ابدأ بـ 60 ثانية وزيّد تدريجياً إذا احتاج.\n\nملاحظة: القيم تقريبية: البروتين 16–17غ (اعتمدنا 16.5) والدهون 17–18غ (اعتمدنا 17.5).","items":[{"food":"بودنق التشوكلت","portion":"صحن","protein":16.5,"carbs":64,"fat":17.5}]}]},{"name":"قالب قليل الكارب","notes":"أقل كارب ممكن من وصفات الكتيب. مكوّن من وصفات كتيب الوصفات: فطور، غداء، عشاء، سناك. الأرقام كما في الكتيب. المجموع تقريباً 1435 سعرة (بروتين 159غ، كارب 59غ، دهون 63غ).","meals":[{"kind":"breakfast","title":"بيض مخفوق مع الجبن والديك الرومي","method":"المكونات:\n• 2 بيضة كاملة\n• 3 بياض بيض\n• 100غ شرايح ديك رومي مدخّن قليل الدهون\n• 30غ جبن قريش أو جبن قليل الدسم\n• 1 ملعقة صغيرة زيت زيتون\n• رشة ملح وفلفل أسود\n\nالطريقة:\n1. نسخّن زيت الزيتون بالمقلاة.\n2. نخفق البيض ونضيفه للمقلاة مع شرايح الديك الرومي.\n3. نضيف الجبن بالآخر ونتركه يذوب شوي، ونقدّمه سخن.","items":[{"food":"بيض مخفوق مع الجبن والديك الرومي","portion":"وجبة كاملة","protein":45,"carbs":5,"fat":22}]},{"kind":"lunch","title":"سمك السلمون المشوي مع البطاطا الحلوة","method":"المكونات:\n• 150غ فيليه سلمون\n• نص كوب بطاطا حلوة مشوية\n• 1 ملعقة صغيرة زيت زيتون\n• نص ملعقة صغيرة بهارات (بابريكا، ملح، فلفل)\n\nالطريقة:\n1. نتبّل السلمون بالملح والبابريكا ونشويه بالفرن أو بالمقلاة لين ينضج، تقريباً 15–20 دقيقة.\n2. نشوي البطاطا الحلوة بزيت الزيتون بالفرن لين تصير ذهبية.","items":[{"food":"سمك السلمون المشوي مع البطاطا الحلوة","portion":"وجبة كاملة","protein":35,"carbs":21,"fat":25}]},{"kind":"dinner","title":"ستيك لحم بالفطر مع رز","method":"المكونات:\n• 200غ ستيك برازيلي\n• 100غ رز أبيض مطبوخ\n• فطر بني\n• 1 ملعقة صغيرة زيت زيتون\n• رشة ملح وفلفل أسود وبودرة ثوم\n\nالطريقة:\n1. نسخّن المقلاة على حرارة عالية، ونحط الستيك من جهة الدهن أول دقيقة لين يتحمّر.\n2. بعدها نحطه كامل على المقلاة على نار متوسطة، 3 دقايق لكل جهة إذا نبيه Medium Well.\n3. نضيف الفطر ونقلّبه لين ينضج اللحم.\n4. نقدّمه مع الرز.","items":[{"food":"ستيك لحم بالفطر مع رز","portion":"وجبة كاملة","protein":54,"carbs":27,"fat":14}]},{"kind":"snack","title":"تشيز كيك البروتين بالفراولة","method":"المكونات:\n• 60غ جبن قريش قليل الدسم\n• نص سكوب واي بروتين نكهة فانيلا\n• 60غ زبادي يوناني\n• نص ملعقة صغيرة فانيلا\n• 1 ملعقة صغيرة ستيفيا\n• 2 حبة فراولة مقطّعة\n\nالطريقة:\n1. نخلط كل المكونات ما عدا الفراولة بالخلاط لين نحصل على قوام كريمي.\n2. نسكب الخليط بكوب ونقدّمه مع الفراولة فوق.\n3. نبرّده بالثلاجة 30 دقيقة عشان يصير ألذ.","items":[{"food":"تشيز كيك البروتين بالفراولة","portion":"كوب","protein":25,"carbs":6,"fat":1.5}]}]}]$rt$::jsonb;
  p jsonb; m jsonb; it jsonb;
  v_plan uuid; v_meal uuid; i int; j int; k int;
BEGIN
  IF EXISTS (SELECT 1 FROM nutrition_plans WHERE order_id IS NULL AND lower(trim(name)) IN (SELECT lower(trim(x->>'name')) FROM jsonb_array_elements(d) x)) THEN
    RAISE EXCEPTION 'هذا الملف مطبّق من قبل (القوالب موجودة). لا حاجة لتشغيله مرة ثانية. اضغطي ROLLBACK.';
  END IF;
  i := 100 + (SELECT count(*) FROM nutrition_plans WHERE order_id IS NULL);
  FOR p IN SELECT * FROM jsonb_array_elements(d) LOOP
    INSERT INTO nutrition_plans (name, notes, position) VALUES (p->>'name', p->>'notes', i) RETURNING id INTO v_plan;
    i := i + 1; j := 0;
    FOR m IN SELECT * FROM jsonb_array_elements(p->'meals') LOOP
      INSERT INTO plan_meals (plan_id, kind, title, method, position) VALUES (v_plan, m->>'kind', m->>'title', nullif(m->>'method', ''), j) RETURNING id INTO v_meal;
      k := 0;
      FOR it IN SELECT * FROM jsonb_array_elements(m->'items') LOOP
        INSERT INTO plan_items (meal_id, food, portion, protein, carbs, fat, position)
        VALUES (v_meal, it->>'food', nullif(it->>'portion', ''), (it->>'protein')::numeric, (it->>'carbs')::numeric, (it->>'fat')::numeric, k);
        k := k + 1;
      END LOOP;
      j := j + 1;
    END LOOP;
  END LOOP;
END $do$;

SELECT p.name, round(sum(i.protein*4 + i.carbs*4 + i.fat*9)) AS kcal, count(DISTINCT m.id) AS meals
  FROM nutrition_plans p JOIN plan_meals m ON m.plan_id = p.id JOIN plan_items i ON i.meal_id = m.id
 WHERE p.order_id IS NULL AND p.position >= 100 GROUP BY p.name, p.position ORDER BY p.position;
COMMIT;
